const aiResponse = $input.item.json.output;
const userId = $json.userId;

const tavilyMatch = aiResponse.match(/tavily\(query="(.+?)"\)/);

if (tavilyMatch) {
  return {
    json: {
      isQuery: true,
      tavilyQuery: tavilyMatch[1],
      userId: userId
    }
  };
} else {
  // Полная очистка для Telegram
  const cleanText = aiResponse
    .replace(/[`*_\[\](){}<>~#]/g, '') // удаляем все форматирование
    .replace(/&[a-z]+;/gi, '')         // удаляем HTML entities
    .replace(/\n{3,}/g, '\n\n');       // не больше 2 переносов подряд

  // Разделяем на части по 300 символов
  const maxLength = 300;
  const parts = [];

  for (let i = 0; i < cleanText.length; i += maxLength) {
    let part = cleanText.substring(i, i + maxLength);
    if (i + maxLength < cleanText.length) {
      part += '...';
    }
    parts.push(part);
  }

  // Возвращаем первую часть
  return {
    json: {
      isQuery: false,
      message: parts[0],
      totalParts: parts.length,
      currentPart: 1,
      userId: userId,
      originalLength: aiResponse.length
    }
  };
}

