const telegramData = $('Telegram Trigger').item.json;
const userId = telegramData.message.chat.id.toString();
const userMessageRaw = telegramData.message.text || '';
const userMessage = userMessageRaw.trim().toLowerCase();

// ПРОСТАЯ ЛОГИКА БЕЗ STATIC DATA
let mode = 'collect_info';

// Если пользователь пишет "да" - значит подтверждает план
if (userMessage === 'да' || userMessage === 'yes' || userMessage === 'давай') {
  mode = 'send_post';
}

// Если это начало диалога
if (userMessage === '/start') {
  mode = 'collect_info';
}

// Если это уровень (после темы)
if (userMessage.includes('началь') || userMessage.includes('средн') || userMessage.includes('продвинут')) {
  mode = 'collect_info'; // AI Agent создаст план
}

// Если это тема обучения
if (userMessage.includes('python') || userMessage.includes('пайтон') || 
    userMessage.includes('программир') || userMessage.includes('научиться')) {
  mode = 'collect_info'; // AI Agent спросит уровень
}

return [{
  json: {
    userId,
    mode,
    userMessage: userMessageRaw,
    switchMode: mode, // для Switch
    topic: userMessage.includes('python') ? 'Python' : 
           userMessage.includes('пайтон') ? 'Python' : '',
    level: userMessage.includes('средн') ? 'средний' : 
           userMessage.includes('началь') ? 'начальный' : 
           userMessage.includes('продвинут') ? 'продвинутый' : ''
  }
}];

const aiResponse = $input.item.json.output;
const userId = $json.userId;

const staticData = $getWorkflowStaticData('global');

if (!staticData.users) {
  staticData.users = {};
}

if (!staticData.users[userId]) {
  staticData.users[userId] = {};
}

// 🛑 ГАРД: если план уже существует — НЕ ПЕРЕСОЗДАЁМ
if (staticData.users[userId].plan && staticData.users[userId].plan.confirmed) {
  return {
    json: {
      message: aiResponse,
      userId
    }
  };
}

// 🛑 ГАРД: проверяем, что это реально учебный план
if (!aiResponse.includes('Тема')) {
  return {
    json: {
      message: aiResponse,
      userId
    }
  };
}

// ===== ПАРСИНГ ПЛАНА =====
const lines = aiResponse.split('\n');
let themes = [];
let currentTheme = null;

for (let rawLine of lines) {
  const line = rawLine.trim();

  // Ловим "Тема X:"
  if (/тема\s+\d+/i.test(line)) {
    if (currentTheme) themes.push(currentTheme);

    const name = line.split(':')[1]?.trim() || 'Тема';

    currentTheme = {
      name,
      concepts: [],
      completed: []
    };
  }

  // Ловим пункты
  if (
    currentTheme &&
    (line.startsWith('-') || line.startsWith('–'))
  ) {
    const concept = line.replace(/^[-–]\s*/, '').trim();
    if (concept) {
      currentTheme.concepts.push(concept);
      currentTheme.completed.push(false);
    }
  }
}

if (currentTheme) themes.push(currentTheme);

// 🛑 Если ничего не распарсили — выходим
if (themes.length === 0) {
  return {
    json: {
      message: aiResponse,
      userId
    }
  };
}

// ===== СОХРАНЕНИЕ =====
staticData.users[userId].plan = {
  themes,
  currentTheme: 0,
  currentConcept: 0,
  confirmed: false
};

return {
  json: {
    message: aiResponse,
    userId,
    DEBUG_savedThemes: themes.length
  }
};

const userId = $json.userId;
const userMessage = $json.userMessage.toLowerCase();

// Проверяем подтвердил ли пользователь
if (userMessage.includes('да') || userMessage.includes('давай') || userMessage.includes('подходит')) {
  // Подтверждаем план
  const staticData = $getWorkflowStaticData('global');
  staticData.users[userId].plan.confirmed = true;

  return {
    json: {
      message: "Отлично! Начинаем обучение! 🎓\n\nНапиши что угодно, и я пришлю первый пост.",
      userId: userId,
      confirmed: true
    }
  };
} else {
  // Еще ждем подтверждения
  return {
    json: {
      message: "Жду твоего подтверждения! Напиши 'Да' если план подходит 😊",
      userId: userId,
      confirmed: false
    }
  };
}

const userId = $json.userId;
const staticData = $getWorkflowStaticData('global');
const plan = staticData.users[userId].plan;

const themeIdx = plan.currentTheme;
const conceptIdx = plan.currentConcept;

// Проверяем, не закончились ли все темы
if (themeIdx >= plan.themes.length) {
  return {
    json: {
      allCompleted: true,
      userId: userId,
      message: "🎉 Поздравляю! Ты прошел все темы!\n\nЧто хочешь изучать дальше?"
    }
  };
}

const theme = plan.themes[themeIdx];
const concept = theme.concepts[conceptIdx];

return {
  json: {
    allCompleted: false,
    userId: userId,
    themeName: theme.name,
    conceptName: concept,
    themeIndex: themeIdx,
    conceptIndex: conceptIdx
  }
};

const userId = $json.userId;
const staticData = $getWorkflowStaticData('global');

// Удаляем план пользователя
delete staticData.users[userId];

return {
  json: {
    message: $json.message,
    userId: userId
  }
};

const aiResponse = $input.item.json.output;
const tavilyMatch = aiResponse.match(/tavily\(query="(.+?)"\)/);

return {
  json: {
    tavilyQuery: tavilyMatch ? tavilyMatch[1] : `${$json.conceptName} подробное объяснение примеры`,
    userId: $json.userId,
    themeName: $json.themeName,
