const userId = $json.userId;
const themeIdx = $json.themeIndex;
const conceptIdx = $json.conceptIndex;
const postMessage = $input.item.json.output;

// Получаем Static Data
const staticData = $getWorkflowStaticData('global');
const plan = staticData.users[userId].plan;

// Отмечаем понятие как пройденное
plan.themes[themeIdx].completed[conceptIdx] = true;

// Ищем следующее непройденное понятие
let nextTheme = themeIdx;
let nextConcept = conceptIdx + 1;

// Если понятия в теме закончились, переходим к следующей теме
if (nextConcept >= plan.themes[themeIdx].concepts.length) {
  nextTheme++;
  nextConcept = 0;
}

// Обновляем текущую позицию
plan.currentTheme = nextTheme;
plan.currentConcept = nextConcept;

return {
  json: {
    message: postMessage,
    userId: userId
  }
};

// Эта нода просто покажет что возвращает Check User State
const inputData = $input.first().json;

return [{
  json: {
    // Данные от Check User State
    mode: inputData.mode,
    userMessage: inputData.userMessage,
    hasPlan: inputData.hasPlan,
    planConfirmed: inputData.planConfirmed,

    // Проверка Static Data напрямую
    staticDataCheck: {
      hasStaticData: !!$getWorkflowStaticData('global').users,
      userExists: !!$getWorkflowStaticData('global').users?.[inputData.userId],
      userPlanExists: !!$getWorkflowStaticData('global').users?.[inputData.userId]?.plan,
      planConfirmed: $getWorkflowStaticData('global').users?.[inputData.userId]?.plan?.confirmed
    },

    timestamp: new Date().toISOString()
  }
}];;

const userId = $json.userId;
const staticData = $getWorkflowStaticData('global');

return [{
  json: {
    debug: 'Проверка Static Data после сохранения',
    userId: userId,
    staticDataExists: !!staticData.users,
    userExists: !!staticData.users?.[userId],
    planExists: !!staticData.users?.[userId]?.plan,
    planConfirmed: staticData.users?.[userId]?.plan?.confirmed,
    // Посмотрим всю структуру
    fullData: staticData.users?.[userId] || 'нет данных'
  }
}];
